INSERT INTO public.courses (id, language_code, title, native_name, level_label, description, sort_order) VALUES
  ('10000000-0000-4000-8000-000000000001', 'en', 'Tiếng Anh', 'English', 'A1 · Cơ bản', 'Bắt đầu với những câu tiếng Anh thiết thực.', 1),
  ('10000000-0000-4000-8000-000000000002', 'fr', 'Tiếng Pháp', 'Français', 'A1 · Cơ bản', 'Làm quen với tiếng Pháp từng ngày.', 2),
  ('10000000-0000-4000-8000-000000000003', 'zh', 'Tiếng Trung', '中文', 'HSK 1', 'Phát âm Pinyin và hội thoại cơ bản.', 3),
  ('10000000-0000-4000-8000-000000000004', 'ja', 'Tiếng Nhật', '日本語', 'JLPT N5', 'Từ mẫu câu cơ bản đến tiếng Nhật thường ngày.', 4)
INSERT INTO public.lessons (id, course_id, title, description, level, category, duration_minutes, sort_order, explanation, example_sentence, example_translation, listening_text, audio_key, is_published, image_key) VALUES
  ('20000000-0000-4000-8000-000000000001', '10000000-0000-4000-8000-000000000001', 'Chào hỏi đầu tiên', 'Cách chào hỏi, hỏi thăm và giới thiệu bản thân.', 'A1', 'Giao tiếp', 10, 1, 'Dùng “I am ...” để giới thiệu và “How are you?” để hỏi thăm. “Nice to meet you” được dùng khi gặp người mới.', 'My name is Anna. Nice to meet you.', 'Tôi tên là Anna. Rất vui được gặp bạn.', 'Hello! My name is Anna. How are you today?', NULL, TRUE, NULL),
  ('20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000000001', 'Gia đình và bạn bè', 'Gọi tên các thành viên gia đình.', 'A1', 'Từ vựng', 12, 2, 'Sở hữu: “my” (của tôi), “your” (của bạn). Dùng “This is my ...” để giới thiệu người thân.', 'This is my sister. She is a student.', 'Đây là chị/em gái của tôi. Cô ấy là học sinh.', 'This is my family. I have one brother and one sister.', NULL, TRUE, NULL),
  ('20000000-0000-4000-8000-000000000003', '10000000-0000-4000-8000-000000000001', 'Thói quen mỗi ngày', 'Nói về các hoạt động quen thuộc trong ngày.', 'A1', 'Ngữ pháp', 14, 3, 'Thì hiện tại đơn: I/you/we/they + động từ nguyên mẫu, he/she/it thường thêm -s/-es. Dùng “every day” cho hoạt động lặp lại.', 'I study English every evening.', 'Tôi học tiếng Anh mỗi tối.', 'I wake up at seven, eat breakfast, and study English in the evening.', NULL, TRUE, NULL),
  ('20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000002', 'Bonjour! Xin chào', 'Lời chào và giới thiệu tiếng Pháp.', 'A1', 'Giao tiếp', 10, 1, '“Bonjour” dùng ban ngày, “Bonsoir” dùng buổi tối. “Je m’appelle ...” để giới thiệu tên, “Merci” là cảm ơn.', 'Bonjour ! Je m’appelle Marie.', 'Xin chào! Tôi tên Marie.', 'Bonjour ! Je m’appelle Marie. Enchantée de faire votre connaissance.', NULL, TRUE, NULL),
  ('20000000-0000-4000-8000-000000000005', '10000000-0000-4000-8000-000000000002', 'Con số từ 1 đến 10', 'Tập đọc số và sử dụng trong câu đơn giản.', 'A1', 'Từ vựng', 12, 2, 'Các số 1–10: un, deux, trois, quatre, cinq, six, sept, huit, neuf, dix. Khi nói tuổi: “J’ai ... ans.”', 'J’ai dix ans.', 'Tôi mười tuổi.', 'Un, deux, trois, quatre, cinq. Nous comptons ensemble.', NULL, TRUE, NULL),
  ('20000000-0000-4000-8000-000000000006', '10000000-0000-4000-8000-000000000002', 'Một ngày thường', 'Câu đơn giản với être, avoir và động từ thường.', 'A1', 'Ngữ pháp', 14, 3, 'Je suis = tôi là; j’ai = tôi có. Ví dụ “Je suis étudiant(e)” và “J’ai un livre”.', 'Je suis étudiant et j’ai un livre.', 'Tôi là sinh viên và tôi có một cuốn sách.', 'Je suis étudiant. Le matin, je lis un livre et je prends un café.', NULL, TRUE, NULL),
  ('20000000-0000-4000-8000-000000000007', '10000000-0000-4000-8000-000000000003', '你好！Chào hỏi', 'Các câu giao tiếp tiếng Trung đầu tiên.', 'HSK 1', 'Giao tiếp', 10, 1, 'Pinyin giúp ghi âm đọc; tiếng Trung phổ thông có 4 thanh chính. “你好” (nǐ hǎo) là xin chào. “我叫...” (wǒ jiào) là tôi tên.', '你好，我叫小明。', 'Xin chào, tôi tên Tiểu Minh.', '你好！我叫小明。你叫什么名字？很高兴认识你。', NULL, TRUE, NULL),
  ('20000000-0000-4000-8000-000000000008', '10000000-0000-4000-8000-000000000003', 'Số đếm và ngày tháng', 'Các số từ 1 đến 10.', 'HSK 1', 'Từ vựng', 12, 2, '一 yī; 二 èr; 三 sān; 四 sì; 五 wǔ; 六 liù; 七 qī; 八 bā; 九 jiǔ; 十 shí. Lưu ý thanh điệu.', '我有三个朋友。', 'Tôi có ba người bạn.', '一、二、三、四、五。我们一起来数数吧。', NULL, TRUE, NULL),
  ('20000000-0000-4000-8000-000000000009', '10000000-0000-4000-8000-000000000003', 'Giới thiệu bản thân', 'Tập ghép câu theo mẫu chủ ngữ + động từ + bổ ngữ.', 'HSK 1', 'Ngữ pháp', 14, 3, 'Mẫu “我是...” = Tôi là...; “你是...吗？” = Bạn có phải ... không? “吗” tạo câu nghi vấn có/không.', '我是越南人。你是学生吗？', 'Tôi là người Việt Nam. Bạn là học sinh phải không?', '你好！我是越南人，我是学生。我喜欢学习中文。', NULL, TRUE, NULL),
  ('20000000-0000-4000-8000-000000000010', '10000000-0000-4000-8000-000000000004', 'はじめまして！', 'Chào hỏi và giới thiệu trong tiếng Nhật.', 'N5', 'Giao tiếp', 10, 1, '“はじめまして” dùng khi lần đầu gặp mặt. “わたしは ... です” = Tôi là... “よろしくおねがいします” dùng sau giới thiệu.', 'はじめまして。わたしはアンです。', 'Rất vui được gặp. Tôi là An.', 'こんにちは。はじめまして。わたしはアンです。よろしくおねがいします。', NULL, TRUE, NULL),
  ('20000000-0000-4000-8000-000000000011', '10000000-0000-4000-8000-000000000004', 'Hiragana cơ bản', 'Làm quen với bảng chữ cái Hiragana.', 'N5', 'Chữ viết', 12, 2, '5 nguyên âm Hiragana: あ(a), い(i), う(u), え(e), お(o). Ghép thành từ và luyện phát âm.', 'あお (ao) = màu xanh dương.', 'あお nghĩa là màu xanh dương.', 'あ、い、う、え、お。あお。いえ。うえ。', NULL, TRUE, NULL),
  ('20000000-0000-4000-8000-000000000012', '10000000-0000-4000-8000-000000000004', 'Trợ từ は và です', 'Tạo câu giới thiệu đơn giản.', 'N5', 'Ngữ pháp', 14, 3, 'Mẫu A は B です = A là B. は ở đây viết “ha” nhưng đọc “wa” khi làm trợ từ chủ đề. です thường kết thúc câu lịch sự.', 'わたしは学生です。', 'Tôi là học sinh.', 'わたしは学生です。これは本です。日本語を勉強します。', NULL, TRUE, NULL)
