INSERT INTO public.exercises (id, lesson_id, prompt, choices, answer_index, explanation, sort_order) VALUES
  ('40000000-0000-4000-8000-000000000001', '20000000-0000-4000-8000-000000000001', 'Cụm từ nào có nghĩa là “Cảm ơn”?', '["Goodbye", "Thank you", "Good morning", "Hello"]'::jsonb, 1, '“Thank you” = Cảm ơn.', 1),
  ('40000000-0000-4000-8000-000000000002', '20000000-0000-4000-8000-000000000001', 'Chọn câu giới thiệu tên đúng.', '["I name Anna", "Me name Anna", "My name is Anna", "Name I Anna"]'::jsonb, 2, '“My name is + tên”.', 2),
  ('40000000-0000-4000-8000-000000000003', '20000000-0000-4000-8000-000000000001', '“How are you?” dùng để làm gì?', '["Hỏi thăm sức khỏe", "Hỏi giá tiền", "Hỏi giờ", "Hỏi tuổi"]'::jsonb, 0, 'Đây là câu hỏi thăm rất phổ biến.', 3),
  ('40000000-0000-4000-8000-000000000004', '20000000-0000-4000-8000-000000000002', '“Sister” nghĩa là gì?', '["Mẹ", "Chị/em gái", "Anh/em trai", "Bạn bè"]'::jsonb, 1, 'Sister = chị hoặc em gái.', 1),
  ('40000000-0000-4000-8000-000000000005', '20000000-0000-4000-8000-000000000002', 'Điền vào câu: This is ___ father.', '["me", "mine", "my", "I"]'::jsonb, 2, 'Trước danh từ dùng tính từ sở hữu “my”.', 2),
  ('40000000-0000-4000-8000-000000000006', '20000000-0000-4000-8000-000000000002', '“Brother” là ai?', '["Anh/em trai", "Bố", "Ông", "Bạn nữ"]'::jsonb, 0, 'Brother = anh/em trai.', 3),
  ('40000000-0000-4000-8000-000000000007', '20000000-0000-4000-8000-000000000003', 'Chọn câu hiện tại đơn đúng.', '["She study English", "She studies English", "She studying English", "She to study English"]'::jsonb, 1, 'Chủ ngữ “she” dùng “studies”.', 1),
  ('40000000-0000-4000-8000-000000000008', '20000000-0000-4000-8000-000000000003', '“Wake up” nghĩa là gì?', '["Đi ngủ", "Thức dậy", "Đi làm", "Ăn sáng"]'::jsonb, 1, 'Wake up = thức dậy.', 2),
